  'phragmidiaceae': { facts: ['Phragmidiaceae (rose rusts) parasitize members of the Rosaceae (rose family) including roses, brambles, and strawberries.', 'Members have distinctive multi-celled teliospores often with ornate surface patterns.', 'The family contains about 200 species.'], distribution: ['Worldwide'], conservationBreakdown: { NE: 160, LC: 25, DD: 15 }, populationTrend: 'stable', habitat: ['Roses', 'Brambles', 'Wild Rosaceae species', 'Gardens'], estimatedPopulation: '~200 described species', extinctSpecies: 0, keyAdaptations: ['Multi-celled teliospores with ornate protuberances', 'Host specialization on Rosaceae family', 'Autoecious life cycles completing on a single host'], trendData: [{ year: 1970, index: 1 }, { year: 1975, index: 1 }, { year: 1980, index: 0.99 }, { year: 1985, index: 0.99 }, { year: 1990, index: 0.98 }, { year: 1995, index: 0.98 }, { year: 2000, index: 0.97 }, { year: 2005, index: 0.97 }, { year: 2010, index: 0.97 }, { year: 2015, index: 0.96 }, { year: 2020, index: 0.96 }, { year: 2024, index: 0.96 }], diversityByRegion: [{ region: 'Europe', count: 60 }, { region: 'Asia', count: 50 }, { region: 'North America', count: 40 }, { region: 'South America', count: 20 }, { region: 'Africa', count: 15 }, { region: 'Oceania', count: 15 }], biomes: ['tropical-rainforest', 'temperate-forest', 'temperate-grassland'] },
