  'cronartium': { facts: ['Cronartium (blister rusts) contains about 40 species, all alternating between pines and various angiosperm alternate hosts.', 'C. ribicola has killed millions of white pines in North America since its accidental introduction around 1910.', 'The hair-like columns of aeciospores erupting from pine bark blisters are among the most dramatic fungal structures.'], distribution: ['North America', 'Europe', 'Asia'], conservationBreakdown: { NE: 32, LC: 6, DD: 2 }, populationTrend: 'stable', habitat: ['Five-needled pines', 'Two-needled pines', 'Ribes (currant) bushes', 'Oaks'], estimatedPopulation: '~40 described species', extinctSpecies: 0, keyAdaptations: ['Perennial bark cankers on pine hosts girdling and killing branches or trunks', 'Column-shaped aecia producing billions of wind-dispersed aeciospores', 'Host alternation between Pinus and diverse angiosperm families'], trendData: [{ year: 1970, index: 1 }, { year: 1975, index: 1.01 }, { year: 1980, index: 1.02 }, { year: 1985, index: 1.03 }, { year: 1990, index: 1.04 }, { year: 1995, index: 1.04 }, { year: 2000, index: 1.05 }, { year: 2005, index: 1.05 }, { year: 2010, index: 1.06 }, { year: 2015, index: 1.06 }, { year: 2020, index: 1.06 }, { year: 2024, index: 1.06 }], diversityByRegion: [{ region: 'North America', count: 14 }, { region: 'Asia', count: 12 }, { region: 'Europe', count: 10 }, { region: 'South America', count: 4 }] },
  'cronartium-ribicola': { facts: ['Cronartium ribicola (white pine blister rust) has killed billions of five-needled pines across North America since its introduction from Asia around 1910.', 'It alternates between white pines (Pinus subgenus Strobus) and Ribes species (currants/gooseberries).', 'The US government spent millions eradicating Ribes bushes near white pine forests in the early-mid 1900s before abandoning the effort.'], distribution: ['North America', 'Europe', 'Asia'], conservationBreakdown: { NE: 1 }, populationTrend: 'stable', habitat: ['White pine forests', 'Five-needled pines', 'Ribes bushes (alternate host)'], estimatedPopulation: 'Established across North American white pine range', extinctSpecies: 0, keyAdaptations: ['Perennial bark cankers slowly girdling and killing pine branches and trunks', 'Wind-dispersed aeciospores traveling long distances from pine to Ribes', 'Basidiospore infection of pine needles via stomata'], trendData: [{ year: 1970, index: 1 }, { year: 1975, index: 1.02 }, { year: 1980, index: 1.04 }, { year: 1985, index: 1.06 }, { year: 1990, index: 1.08 }, { year: 1995, index: 1.1 }, { year: 2000, index: 1.11 }, { year: 2005, index: 1.12 }, { year: 2010, index: 1.12 }, { year: 2015, index: 1.12 }, { year: 2020, index: 1.12 }, { year: 2024, index: 1.12 }], diversityByRegion: [{ region: 'North America', count: 1 }, { region: 'Europe', count: 1 }, { region: 'Asia', count: 1 }], biomes: ['tropical-rainforest', 'temperate-forest', 'boreal-forest'] },
