  'cladonia': { facts: ['Cladonia (reindeer lichens and pixie cups) contains about 400 species, dominating many tundra landscapes.', 'Caribou can smell C. rangiferina beneath snow and dig through to feed on it during winter.', 'Growth rate is extremely slow — only 3-5 mm per year.'], distribution: ['Worldwide'], conservationBreakdown: { NE: 220, LC: 100, DD: 50, VU: 20, EN: 8, CR: 2 }, populationTrend: 'decreasing', habitat: ['Boreal forest floor', 'Tundra', 'Sandy heaths', 'Rotten stumps'], estimatedPopulation: '~400 described species', extinctSpecies: 3, keyAdaptations: ['Podetia bearing apothecia or soredia above ground layer', 'Extremely slow growth rate but very long-lived (centuries)', 'Caribou-palatability providing key Arctic food web link'], trendData: [{ year: 1970, index: 1 }, { year: 1975, index: 0.98 }, { year: 1980, index: 0.96 }, { year: 1985, index: 0.94 }, { year: 1990, index: 0.92 }, { year: 1995, index: 0.9 }, { year: 2000, index: 0.88 }, { year: 2005, index: 0.86 }, { year: 2010, index: 0.84 }, { year: 2015, index: 0.82 }, { year: 2020, index: 0.8 }, { year: 2024, index: 0.79 }], diversityByRegion: [{ region: 'North America', count: 100 }, { region: 'Europe', count: 90 }, { region: 'South America', count: 80 }, { region: 'Asia', count: 60 }, { region: 'Oceania', count: 40 }, { region: 'Africa', count: 30 }], biomes: ['tropical-rainforest', 'temperate-forest', 'boreal-forest', 'tundra'] },
